with matched_keys as (select id, product_id from order_items intersect all select id, product_id from order_items where quantity > 4), reconciled as (select s.* from order_items s inner join matched_keys k on s.id = k.id and s.product_id = k.product_id) select case when unit_price >= 430 then 'LARGE' else 'SMALL' end as unit_price_tier, bit_and(quantity) as quantity_bit_and, bit_and(quantity) as quantity_bit_and_2, round(avg(unit_price), 2) as avg_unit_price from reconciled group by case when unit_price >= 430 then 'LARGE' else 'SMALL' end having bit_and(quantity) >= 1
